import type { Ref } from 'vue'
import { createContext } from 'reka-ui'
import type { FileTreeSize } from './types'

/** One drag session. Shared by every drop target inside a `FileExplorer`. */
/** Inline rename, shared by tree nodes, cards and rows. */
export interface FileExplorerRenameContext {
  /** The item showing a rename input, if any. */
  renamingId: Readonly<Ref<string | null>>
  validateRename: (id: string, name: string) => string | undefined
  commitRename: (id: string, name: string) => void
  cancelRename: (id: string) => void
}

export interface FileExplorerDragDrop {
  draggingIds: Readonly<Ref<readonly string[]>>
  /** Folder currently under the pointer; `null` is the root, `undefined` is none. */
  dropTargetId: Readonly<Ref<string | null | undefined>>
  onDragStart: (id: string, event: DragEvent) => void
  onDragOver: (id: string | null, event: DragEvent) => void
  onDrop: (event: DragEvent) => void
  onDragEnd: () => void
  onDragLeave: (event: DragEvent) => void
}

/**
 * State shared from `FileTree` with every recursive node. It is id-based on
 * purpose: nodes receive their item as a prop, so nothing here depends on the
 * consumer's `data` type, and a node never needs a watcher of its own.
 */
export interface FileTreeContext extends FileExplorerRenameContext {
  /** Trimmed search query, used to highlight matches. */
  query: Readonly<Ref<string>>
  size: Readonly<Ref<FileTreeSize>>
  guides: Readonly<Ref<boolean>>
  draggable: Readonly<Ref<boolean>>
  dragDrop: FileExplorerDragDrop
  onItemSelect: (id: string, event: Event) => void
  onItemOpen: (id: string) => void
  onItemContextMenu: (id: string) => void
  foldersOnly: Readonly<Ref<boolean>>
  /** Whether clicking a folder row (not its chevron) also opens or closes it. */
  expandOnClick: Readonly<Ref<boolean>>
  extendSelection: (id: string) => void
  selectAll: () => void
  /** F2 on a node. */
  startRename: (id: string) => void
  /** Delete on a node. */
  deleteFrom: (id: string) => void
}

export const [injectFileTreeContext, provideFileTreeContext]
  = createContext<FileTreeContext>('FileTree')

/**
 * Lets a `FileTree` rendered inside a `FileExplorer` join the explorer's drag
 * session, so items can be dragged between the sidebar, the cards and the
 * breadcrumbs. A standalone tree runs its own.
 */
export const [injectSharedDragDrop, provideSharedDragDrop]
  = createContext<FileExplorerDragDrop>('FileExplorerDragDrop')

/** State shared from `FileExplorer` with its toolbar, cards, rows and status bar. */
export interface FileExplorerContext extends FileExplorerRenameContext {
  selected: Readonly<Ref<ReadonlySet<string>>>
  /** The item holding the roving tab stop in the content area. */
  focusedId: Readonly<Ref<string | null>>
  /** Ticks every minute, for "5m ago" labels. */
  now: Readonly<Ref<Date>>
  draggable: Readonly<Ref<boolean>>
  dragDrop: FileExplorerDragDrop
  onItemClick: (id: string, event: MouseEvent) => void
  /** Double-click or Enter: folders navigate, files emit `open`. */
  onItemOpen: (id: string) => void
  onItemContextMenu: (id: string) => void
}

export const [injectFileExplorerContext, provideFileExplorerContext]
  = createContext<FileExplorerContext>('FileExplorer')

import type { Component, HTMLAttributes } from 'vue'

export type FileExplorerItemType = 'file' | 'folder'

/**
 * A node in the tree. Folders hold their children; files never need `children`.
 *
 * `TData` types the optional `data` field, so application metadata travels with
 * the node and comes back fully typed in slots and events.
 */
export interface FileExplorerItem<TData = unknown> {
  /** Stable, unique identifier. Selection, expansion and rendering keys all use it — never the name. */
  id: string
  name: string
  type: FileExplorerItemType
  /** A folder's contents. Omit it or pass `[]` for an empty folder. Ignored on files. */
  children?: FileExplorerItem<TData>[]
  /** Size in bytes. */
  size?: number
  modifiedAt?: Date | string
  /** Overrides the extension parsed from `name` when resolving the default icon. */
  extension?: string
  mimeType?: string
  /** Subtitle on explorer cards. Defaults to the file type, e.g. "Vue component". */
  description?: string
  /** A few lines of text shown on the explorer card, e.g. the start of a source file. */
  preview?: string
  /** Image URL shown on the explorer card instead of `preview`. */
  thumbnail?: string
  disabled?: boolean
  /** Arbitrary application data. */
  data?: TData
}

/** Interaction state of a rendered item, passed to slots and the icon resolver. */
export interface FileExplorerItemState {
  /** Zero-based nesting depth. Root items are `0`. */
  depth: number
  expanded: boolean
  selected: boolean
  disabled: boolean
}

export type FileExplorerIconResolver<TData = unknown> = (
  item: FileExplorerItem<TData>,
  state: FileExplorerItemState,
) => Component | undefined

export type FileTreeSize = 'sm' | 'md'

export interface FileExplorerSelectEvent<TData = unknown> {
  /** The item the user interacted with. */
  item: FileExplorerItem<TData>
  /** The full selection after the interaction. */
  selected: string[]
  originalEvent: Event
}

export interface FileExplorerMoveEvent<TData = unknown> {
  /** The dragged items. Items nested inside another dragged folder are left out. */
  items: FileExplorerItem<TData>[]
  /** The destination folder, or `null` for the root. */
  target: FileExplorerItem<TData> | null
}

export interface FileExplorerItemSlotProps<TData = unknown> extends FileExplorerItemState {
  item: FileExplorerItem<TData>
}

export interface FileExplorerLabelSlotProps<TData = unknown> extends FileExplorerItemSlotProps<TData> {
  /** The active search query, trimmed. Empty when not searching. */
  query: string
}

export interface FileTreeNodeSlots<TData = unknown> {
  /** Replaces the icon and label of every item. The chevron, indentation and row stay in place. */
  item?: (props: FileExplorerItemSlotProps<TData>) => unknown
  icon?: (props: FileExplorerItemSlotProps<TData>) => unknown
  label?: (props: FileExplorerLabelSlotProps<TData>) => unknown
  /** Trailing content, pushed to the end of the row. */
  actions?: (props: FileExplorerItemSlotProps<TData>) => unknown
}

/** Scope of the `#context-menu` slot of `FileTree` and `FileExplorer`. */
export interface FileExplorerContextMenuSlotProps<TData = unknown> {
  /** The item that was right-clicked, or `null` for the empty area. */
  item: FileExplorerItem<TData> | null
  /** Starts renaming `item` inline once the menu has closed. Needs `onRename`. */
  rename: () => void
  /**
   * Deletes `item` — or the whole selection when `item` is part of it — after
   * the confirmation dialog. Needs `onDelete`.
   */
  remove: () => void
}

/** Validates a new name. Return an error message to refuse it. */
export type FileExplorerNameValidator<TData = unknown> = (name: string, item: FileExplorerItem<TData>) => string | undefined

export interface FileTreeSlots<TData = unknown> extends FileTreeNodeSlots<TData> {
  /** Menu entries shown on right-click. `item` is `null` when the empty area was clicked. */
  'context-menu'?: (props: FileExplorerContextMenuSlotProps<TData>) => unknown
  empty?: (props: { query: string }) => unknown
  loading?: (props: Record<string, never>) => unknown
  /** Body of the delete confirmation dialog. */
  'delete-description'?: (props: { items: FileExplorerItem<TData>[] }) => unknown
}

export interface FileTreeProps<TData = unknown> {
  items?: FileExplorerItem<TData>[]
  /** Selected ids. Bind with `v-model:selected`. Always an array, even without `multiple`. */
  selected?: string[]
  /** Initial selection when `selected` is not bound. */
  defaultSelected?: string[]
  /** Expanded folder ids. Bind with `v-model:expanded`. */
  expanded?: string[]
  /** Initially expanded folder ids when `expanded` is not bound. */
  defaultExpanded?: string[]
  /** Filter query. Bind with `v-model:search`, or let `searchable` manage it. */
  search?: string
  /** Allows Ctrl/Cmd-click, Shift-click, Shift+Arrow and Ctrl/Cmd+A to select several items. */
  multiple?: boolean
  /** Renders a search field above the tree. */
  searchable?: boolean
  searchPlaceholder?: string
  /** Replaces the tree with skeleton rows (or the `loading` slot). */
  loading?: boolean
  disabled?: boolean
  /** Enables drag and drop. Listen to `move` to apply the change. */
  draggable?: boolean
  /** Picks the icon for an item. Return `undefined` to fall back to the default icon. */
  getIcon?: FileExplorerIconResolver<TData>
  size?: FileTreeSize
  /** Draws indent guides next to nested items. */
  guides?: boolean
  /** Hides files, like the navigation pane of a desktop file manager. */
  foldersOnly?: boolean
  /** Clicking a folder row opens or closes it. When `false`, only the chevron and arrow keys do. */
  expandOnClick?: boolean
  /** Accessible name of the tree. */
  label?: string
  /** Called with the new name after an inline rename (F2 or the context menu). Enables renaming. */
  onRename?: (item: FileExplorerItem<TData>, name: string) => void
  /** Extra checks for new names. Empty names and duplicates in the same folder are always refused. */
  validateName?: FileExplorerNameValidator<TData>
  /** Called with the selection on Delete, or from the context menu. Enables deleting. */
  onDelete?: (items: FileExplorerItem<TData>[]) => void
  /** Asks for confirmation in a dialog before calling `onDelete`. */
  confirmDelete?: boolean
  class?: HTMLAttributes['class']
}

export interface FileTreeEmits<TData = unknown> {
  'update:selected': [value: string[]]
  'update:expanded': [value: string[]]
  'update:search': [value: string]
  /** The user selected an item with the pointer or keyboard. */
  select: [event: FileExplorerSelectEvent<TData>]
  /** A file was activated with Enter or a double-click. */
  open: [item: FileExplorerItem<TData>]
  /** Items were dropped on a folder (or the root). Only with `draggable`. */
  move: [event: FileExplorerMoveEvent<TData>]
}

// --- FileExplorer ---------------------------------------------------------------

export type FileExplorerView = 'grid' | 'list'
export type FileExplorerSortKey = 'name' | 'modified' | 'type' | 'size'

export interface FileExplorerSort {
  key: FileExplorerSortKey
  direction: 'asc' | 'desc'
}

export interface FileExplorerProps<TData = unknown> {
  items?: FileExplorerItem<TData>[]
  /** Id of the open folder, `null` for the root. Bind with `v-model:folder`. */
  folder?: string | null
  defaultFolder?: string | null
  /** Selected ids in the open folder. Bind with `v-model:selected`. */
  selected?: string[]
  defaultSelected?: string[]
  /** Bind with `v-model:view`. */
  view?: FileExplorerView
  defaultView?: FileExplorerView
  /** Filters the open folder by name. Bind with `v-model:search`. */
  search?: string
  /** Bind with `v-model:sort`. Folders always come first. */
  sort?: FileExplorerSort
  /** Ctrl/Cmd-click, Shift-click, Shift+Arrow and Ctrl/Cmd+A. */
  multiple?: boolean
  /** Drag items onto folders, the directory tree or the breadcrumbs. Listen to `move`. */
  draggable?: boolean
  /** Shows the directory tree when the explorer is wide enough. */
  sidebar?: boolean
  loading?: boolean
  disabled?: boolean
  /** Label of the root in the breadcrumbs. */
  rootLabel?: string
  /** `accept` attribute of the upload picker. */
  accept?: string
  /** Icon for tree nodes and details rows. Cards use colored type tiles. */
  getIcon?: FileExplorerIconResolver<TData>
  /** Accessible name of the item list. */
  label?: string
  class?: HTMLAttributes['class']
  /**
   * Called with picked or dropped files and the destination folder. Providing it
   * shows the Upload button and the drop tile, and accepts files dropped from the desktop.
   */
  onUpload?: (files: File[], folder: FileExplorerItem<TData> | null) => void
  /** Called by the New Folder button, which only appears when this is provided. */
  onCreateFolder?: (parent: FileExplorerItem<TData> | null) => void
  /** Called with the new name after an inline rename (F2 or the context menu). Enables renaming. */
  onRename?: (item: FileExplorerItem<TData>, name: string) => void
  /** Extra checks for new names. Empty names and duplicates in the same folder are always refused. */
  validateName?: FileExplorerNameValidator<TData>
  /** Called with the items to delete: the selection on Delete, or from the context menu. */
  onDelete?: (items: FileExplorerItem<TData>[]) => void
  /** Asks for confirmation in a dialog before calling `onDelete`. */
  confirmDelete?: boolean
}

export interface FileExplorerEmits<TData = unknown> {
  'update:folder': [id: string | null]
  'update:selected': [value: string[]]
  'update:view': [value: FileExplorerView]
  'update:search': [value: string]
  'update:sort': [value: FileExplorerSort]
  /** A file was opened with a double-click, Enter or the status bar. */
  open: [item: FileExplorerItem<TData>]
  /** Items were dropped on a folder, or on a breadcrumb (`target: null` is the root). */
  move: [event: FileExplorerMoveEvent<TData>]
}

export interface FileExplorerSlots<TData = unknown> {
  /** Replaces the preview area of a card. */
  preview?: (props: { item: FileExplorerItem<TData> }) => unknown
  /** Menu entries for right-clicks on items, the empty area and the directory tree. */
  'context-menu'?: (props: FileExplorerContextMenuSlotProps<TData>) => unknown
  /** Body of the delete confirmation dialog. */
  'delete-description'?: (props: { items: FileExplorerItem<TData>[] }) => unknown
  empty?: (props: { query: string }) => unknown
  /** Extra toolbar buttons, before New Folder and Upload. */
  'toolbar-actions'?: (props: Record<string, never>) => unknown
  /** Actions at the end of the status bar. Defaults to an Open button for a single file. */
  'status-actions'?: (props: { items: FileExplorerItem<TData>[] }) => unknown
}

import type { Component } from 'vue'
import {
  File,
  FileArchive,
  FileAudio,
  FileCode,
  FileCog,
  FileImage,
  FileJson,
  FileLock,
  FileSpreadsheet,
  FileTerminal,
  FileText,
  FileType,
  FileVideo,
  Folder,
  FolderOpen,
} from 'lucide-vue-next'
import type { FileExplorerItem, FileExplorerItemState, FileExplorerSort } from './types'

export interface FileExplorerIndexEntry<TData = unknown> {
  item: FileExplorerItem<TData>
  parentId: string | null
  depth: number
}

export type FileExplorerIndex<TData = unknown> = Map<string, FileExplorerIndexEntry<TData>>

export function isFolder<TData>(item: FileExplorerItem<TData>): boolean {
  return item.type === 'folder'
}

/**
 * One pass over the tree that maps every id to its item, parent and depth.
 * Items are referenced, never copied.
 */
export function indexFileTree<TData>(items: FileExplorerItem<TData>[]): FileExplorerIndex<TData> {
  const index: FileExplorerIndex<TData> = new Map()
  const visit = (nodes: FileExplorerItem<TData>[], parentId: string | null, depth: number) => {
    for (const item of nodes) {
      index.set(item.id, { item, parentId, depth })
      if (item.children?.length) visit(item.children, item.id, depth + 1)
    }
  }
  visit(items, null, 0)
  return index
}

/** A folders-only copy of the tree. Folders on the way are shallow-copied; the input is untouched. */
export function pruneFiles<TData>(items: FileExplorerItem<TData>[]): FileExplorerItem<TData>[] {
  return items.flatMap(item => (isFolder(item) ? [{ ...item, children: pruneFiles(item.children ?? []) }] : []))
}

/** Whether `id` sits somewhere below `ancestorId`. */
export function isDescendantOf<TData>(index: FileExplorerIndex<TData>, id: string, ancestorId: string): boolean {
  let parentId = index.get(id)?.parentId ?? null
  while (parentId !== null) {
    if (parentId === ancestorId) return true
    parentId = index.get(parentId)?.parentId ?? null
  }
  return false
}

/** Ids of the items currently on screen, in the order they appear. */
export function getVisibleIds<TData>(items: FileExplorerItem<TData>[], expanded: ReadonlySet<string>): string[] {
  const ids: string[] = []
  const visit = (nodes: FileExplorerItem<TData>[]) => {
    for (const item of nodes) {
      ids.push(item.id)
      if (item.children && expanded.has(item.id)) visit(item.children)
    }
  }
  visit(items)
  return ids
}

export interface FileTreeFilterResult<TData = unknown> {
  items: FileExplorerItem<TData>[]
  /** Folders that must be open for every match to be visible. */
  revealIds: string[]
}

/**
 * Keeps the items whose name contains `query`, plus the folders leading to them.
 *
 * A folder whose own name matches is kept whole. A folder kept only for its
 * descendants is shallow-copied with a filtered `children` array; the input is
 * never mutated.
 */
export function filterFileTree<TData>(items: FileExplorerItem<TData>[], query: string): FileTreeFilterResult<TData> {
  const needle = query.trim().toLowerCase()
  if (!needle) return { items, revealIds: [] }

  const revealIds: string[] = []
  const visit = (nodes: FileExplorerItem<TData>[]): FileExplorerItem<TData>[] => {
    const kept: FileExplorerItem<TData>[] = []
    for (const item of nodes) {
      if (item.name.toLowerCase().includes(needle)) {
        kept.push(item)
        continue
      }
      if (!item.children?.length) continue
      const children = visit(item.children)
      if (children.length) {
        revealIds.push(item.id)
        kept.push({ ...item, children })
      }
    }
    return kept
  }

  return { items: visit(items), revealIds }
}

/** Splits `text` around case-insensitive occurrences of `query`, for highlighting. */
export function splitByQuery(text: string, query: string): { text: string, match: boolean }[] {
  const needle = query.trim().toLowerCase()
  if (!needle) return [{ text, match: false }]

  const parts: { text: string, match: boolean }[] = []
  const haystack = text.toLowerCase()
  let cursor = 0
  let found = haystack.indexOf(needle)
  while (found !== -1) {
    if (found > cursor) parts.push({ text: text.slice(cursor, found), match: false })
    parts.push({ text: text.slice(found, found + needle.length), match: true })
    cursor = found + needle.length
    found = haystack.indexOf(needle, cursor)
  }
  if (cursor < text.length) parts.push({ text: text.slice(cursor), match: false })
  return parts
}

const ICONS_BY_EXTENSION: Record<string, Component> = {}
const register = (icon: Component, extensions: string[]) => {
  for (const extension of extensions) ICONS_BY_EXTENSION[extension] = icon
}
register(FileCode, ['vue', 'ts', 'tsx', 'mts', 'cts', 'js', 'jsx', 'mjs', 'cjs', 'html', 'css', 'scss', 'sass', 'less', 'svelte', 'astro', 'py', 'go', 'rs', 'java', 'kt', 'swift', 'rb', 'php', 'c', 'h', 'cpp', 'cs', 'sql', 'graphql'])
register(FileJson, ['json', 'jsonc', 'json5'])
register(FileText, ['md', 'mdx', 'txt', 'rtf', 'pdf', 'doc', 'docx'])
register(FileImage, ['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'avif', 'ico', 'bmp'])
register(FileVideo, ['mp4', 'mov', 'webm', 'mkv', 'avi'])
register(FileAudio, ['mp3', 'wav', 'ogg', 'flac', 'm4a'])
register(FileArchive, ['zip', 'tar', 'gz', 'tgz', 'rar', '7z'])
register(FileSpreadsheet, ['csv', 'tsv', 'xls', 'xlsx'])
register(FileTerminal, ['sh', 'bash', 'zsh', 'fish', 'ps1'])
register(FileCog, ['yml', 'yaml', 'toml', 'ini', 'env', 'conf', 'config', 'editorconfig', 'gitignore'])
register(FileLock, ['lock'])
register(FileType, ['ttf', 'otf', 'woff', 'woff2'])

/** Lower-cased extension without the dot. `.env` resolves to `env`; `Makefile` to `''`. */
export function getFileExtension<TData>(item: FileExplorerItem<TData>): string {
  if (item.extension) return item.extension.replace(/^\./, '').toLowerCase()
  const dot = item.name.lastIndexOf('.')
  return dot === -1 ? '' : item.name.slice(dot + 1).toLowerCase()
}

/** The default icon resolver: open/closed folders, and a small set of generic file-type glyphs. */
export function getFileIcon<TData>(item: FileExplorerItem<TData>, state: Pick<FileExplorerItemState, 'expanded'>): Component {
  if (isFolder(item)) return state.expanded ? FolderOpen : Folder
  return ICONS_BY_EXTENSION[getFileExtension(item)] ?? File
}

// --- Explorer helpers ------------------------------------------------------------

export interface FileKind {
  /** Human description, e.g. "Vue component". */
  label: string
  /** Short text for the icon tile ("V", "TS"). Types without one show their icon. */
  badge?: string
  /** Tailwind classes tinting the icon tile. */
  tone: string
}

const NEUTRAL_TONE = 'bg-muted text-muted-foreground'
const KINDS: { extensions: string[], kind: FileKind }[] = [
  { extensions: ['vue'], kind: { label: 'Vue component', badge: 'V', tone: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400' } },
  { extensions: ['ts', 'tsx', 'mts', 'cts'], kind: { label: 'TypeScript', badge: 'TS', tone: 'bg-sky-500/10 text-sky-600 dark:text-sky-400' } },
  { extensions: ['js', 'jsx', 'mjs', 'cjs'], kind: { label: 'JavaScript', badge: 'JS', tone: 'bg-amber-500/10 text-amber-600 dark:text-amber-400' } },
  { extensions: ['json', 'jsonc', 'json5'], kind: { label: 'JSON', badge: '{}', tone: 'bg-amber-500/10 text-amber-600 dark:text-amber-400' } },
  { extensions: ['css', 'scss', 'sass', 'less'], kind: { label: 'Stylesheet', badge: '#', tone: 'bg-pink-500/10 text-pink-600 dark:text-pink-400' } },
  { extensions: ['html'], kind: { label: 'HTML document', badge: '<>', tone: 'bg-orange-500/10 text-orange-600 dark:text-orange-400' } },
  { extensions: ['md', 'mdx'], kind: { label: 'Markdown', badge: 'MD', tone: NEUTRAL_TONE } },
  { extensions: ['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'avif', 'ico', 'bmp'], kind: { label: 'Image', tone: 'bg-violet-500/10 text-violet-600 dark:text-violet-400' } },
  { extensions: ['mp4', 'mov', 'webm', 'mkv', 'avi'], kind: { label: 'Video', tone: 'bg-rose-500/10 text-rose-600 dark:text-rose-400' } },
  { extensions: ['mp3', 'wav', 'ogg', 'flac', 'm4a'], kind: { label: 'Audio', tone: 'bg-rose-500/10 text-rose-600 dark:text-rose-400' } },
  { extensions: ['pdf'], kind: { label: 'PDF document', tone: 'bg-red-500/10 text-red-600 dark:text-red-400' } },
]
const KIND_BY_EXTENSION = new Map(KINDS.flatMap(({ extensions, kind }) => extensions.map(extension => [extension, kind] as const)))

/** Describes an item for cards, the details view and the status bar. */
export function getFileKind<TData>(item: FileExplorerItem<TData>): FileKind {
  if (isFolder(item)) return { label: 'Folder', tone: NEUTRAL_TONE }
  const extension = getFileExtension(item)
  const kind = KIND_BY_EXTENSION.get(extension)
  if (kind?.label === 'Image' || kind?.label === 'Video' || kind?.label === 'Audio')
    return { ...kind, label: `${extension.toUpperCase()} ${kind.label.toLowerCase()}` }
  if (kind) return kind
  if (/\.config\.[a-z]+$/i.test(item.name)) return { label: 'Configuration', tone: NEUTRAL_TONE }
  return { label: extension ? `${extension.toUpperCase()} file` : 'File', tone: NEUTRAL_TONE }
}

/** `1536` → `"1.5 KB"`. */
export function formatBytes(bytes: number | undefined): string {
  if (bytes === undefined || !Number.isFinite(bytes)) return ''
  const units = ['B', 'KB', 'MB', 'GB', 'TB']
  let value = bytes
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit += 1
  }
  return unit === 0 ? `${value} B` : `${value.toFixed(1)} ${units[unit]}`
}

/** Compact relative time: `"just now"`, `"10m ago"`, `"3d ago"`. */
export function formatRelativeTime(value: Date | string | undefined, now: Date = new Date()): string {
  if (value === undefined) return ''
  const date = value instanceof Date ? value : new Date(value)
  const seconds = Math.round((now.getTime() - date.getTime()) / 1000)
  if (Number.isNaN(seconds)) return ''
  if (seconds < 45) return 'just now'
  const steps: [limit: number, size: number, suffix: string][] = [
    [60 * 60, 60, 'm'],
    [60 * 60 * 24, 60 * 60, 'h'],
    [60 * 60 * 24 * 7, 60 * 60 * 24, 'd'],
    [60 * 60 * 24 * 30, 60 * 60 * 24 * 7, 'w'],
    [60 * 60 * 24 * 365, 60 * 60 * 24 * 30, 'mo'],
  ]
  for (const [limit, size, suffix] of steps) {
    if (seconds < limit) return `${Math.max(1, Math.floor(seconds / size))}${suffix} ago`
  }
  return `${Math.floor(seconds / (60 * 60 * 24 * 365))}y ago`
}

export type CodeTokenKind = 'keyword' | 'string' | 'tag' | 'comment' | 'plain'

const CODE_TOKEN = /(\/\/.*$)|(["'`])(?:\\.|(?!\2).)*\2|(<\/?[A-Za-z][\w.-]*|\/?>)|\b(import|export|default|from|const|let|var|function|return|async|await|if|else|new|type|interface|class|extends|true|false|null)\b/g

/** A deliberately tiny tokenizer for one-glance previews. It is not a syntax highlighter. */
export function tokenizeCode(line: string): { text: string, kind: CodeTokenKind }[] {
  const tokens: { text: string, kind: CodeTokenKind }[] = []
  let cursor = 0
  for (const match of line.matchAll(CODE_TOKEN)) {
    const start = match.index ?? 0
    if (start > cursor) tokens.push({ text: line.slice(cursor, start), kind: 'plain' })
    const kind: CodeTokenKind = match[1] ? 'comment' : match[2] ? 'string' : match[3] ? 'tag' : 'keyword'
    tokens.push({ text: match[0], kind })
    cursor = start + match[0].length
  }
  if (cursor < line.length) tokens.push({ text: line.slice(cursor), kind: 'plain' })
  return tokens
}

const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' })

function timestamp(value: Date | string | undefined): number {
  if (value === undefined) return 0
  const time = (value instanceof Date ? value : new Date(value)).getTime()
  return Number.isNaN(time) ? 0 : time
}

/** Folders first, then by `sort`, then by name — the order every desktop file manager uses. */
export function sortFileItems<TData>(items: FileExplorerItem<TData>[], sort: FileExplorerSort): FileExplorerItem<TData>[] {
  const direction = sort.direction === 'asc' ? 1 : -1
  const byKey = (a: FileExplorerItem<TData>, b: FileExplorerItem<TData>): number => {
    switch (sort.key) {
      case 'modified': return timestamp(a.modifiedAt) - timestamp(b.modifiedAt)
      case 'size': return (a.size ?? 0) - (b.size ?? 0)
      case 'type': return collator.compare(getFileKind(a).label, getFileKind(b).label)
      case 'name': return 0
    }
  }
  return [...items].sort((a, b) => {
    if (isFolder(a) !== isFolder(b)) return isFolder(a) ? -1 : 1
    return (byKey(a, b) || collator.compare(a.name, b.name)) * direction
  })
}

/** Ids from the root down to `id`, inclusive. */
export function getAncestorIds<TData>(index: FileExplorerIndex<TData>, id: string | null): string[] {
  const ids: string[] = []
  let current = id
  while (current !== null) {
    const entry = index.get(current)
    if (!entry) break
    ids.unshift(current)
    current = entry.parentId
  }
  return ids
}

/**
 * Checks a new name for `item`: not empty, no separators, and unique among its
 * siblings (case-insensitively, as on Windows and macOS). Returns an error message.
 */
export function validateItemName<TData>(
  index: FileExplorerIndex<TData>,
  rootItems: FileExplorerItem<TData>[],
  item: FileExplorerItem<TData>,
  name: string,
): string | undefined {
  const trimmed = name.trim()
  if (!trimmed) return 'A name is required.'
  if (/[\\/]/.test(trimmed)) return 'Names cannot contain / or \\.'
  const parentId = index.get(item.id)?.parentId ?? null
  const siblings = parentId === null ? rootItems : index.get(parentId)?.item.children ?? []
  const lower = trimmed.toLowerCase()
  if (siblings.some(sibling => sibling.id !== item.id && sibling.name.toLowerCase() === lower))
    return `An item named “${trimmed}” already exists here.`
  return undefined
}

